# Definir funciones
function saludar {
    echo "¡Hola!"
}

# Función con argumentos
function saludar_usuario {
    local nombre=$1
    local apellido=$2
    echo "¡Hola ${nombre} ${apellido}!"
}

# Llamar funciones
saludar
saludar_usuario "Juan" "Pérez"

# Funciones con valores de retorno

function sumar {
    local a=$1
    local b=$2
    echo $((a + b))
}

resultado=$(sumar 5 3)
echo "Resultado: $resultado"

# Return vs echo
# return = código de salida (0-255)
# echo = valor de retorno

function es_root {
    if [ "$EUID" -eq 0 ]; then
        return 0    # Éxito (true)
    else
        return 1    # Fallo (false)
    fi
}

if es_root; then
    echo "Eres root"
fi
